function keywordSheetInput({ values }) {
  if (!Array.isArray(values)) throw new Error('Expected the complete keyword worksheet values');
  if (values.length === 0) return { rows: [], count: 0 };
  if (!Array.isArray(values[0])) throw new Error('The keyword worksheet needs a header row');
  const headers = values[0];
  for (const name of ['Number', 'Keyword', 'Service?']) if (headers.filter(value => value === name).length !== 1) throw new Error('The first worksheet row must contain exactly one ' + name + ' header');
  const rows = [];
  for (let rowIndex = 1; rowIndex < values.length; rowIndex++) {
    const cells = values[rowIndex];
    if (!Array.isArray(cells)) throw new Error('Invalid keyword worksheet row ' + (rowIndex + 1));
    if (!cells.some(value => value !== null && value !== undefined && value !== '')) continue;
    const row = Object.create(null);
    for (let column = 0; column < cells.length; column++) {
      const header = headers[column] || 'col_' + column;
      if (!['string', 'number', 'boolean'].includes(typeof header)) throw new Error('Invalid keyword worksheet header');
      row[String(header)] = cells[column] ?? '';
    }
    const number = row.Number, keyword = row.Keyword;
    if (!['string', 'number', 'boolean'].includes(typeof number) || (typeof number === 'string' && !number.trim()) || (typeof number === 'number' && !Number.isFinite(number))) throw new Error('Keyword row ' + (rowIndex + 1) + ' needs a Number match key');
    if (!['string', 'number', 'boolean'].includes(typeof keyword) || (typeof keyword === 'string' && !keyword.trim()) || (typeof keyword === 'number' && !Number.isFinite(keyword))) throw new Error('Keyword row ' + (rowIndex + 1) + ' needs a nonblank scalar Keyword');
    rows.push({ index: rows.length, number, keyword: String(keyword), row });
  }
  return { rows, count: rows.length };
}

